-- Invoice & Payment Service schema.
-- Money is always BIGINT cents. IDs are UUIDv7 generated by the app (time-ordered).

CREATE TABLE businesses (
    id          uuid PRIMARY KEY,
    name        text NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT now()
);

-- API keys: we store only a SHA-256 hash. The prefix is a non-secret lookup handle.
CREATE TABLE api_keys (
    id            uuid PRIMARY KEY,
    business_id   uuid NOT NULL REFERENCES businesses (id),
    prefix        text NOT NULL UNIQUE,
    key_hash      bytea NOT NULL,
    created_at    timestamptz NOT NULL DEFAULT now(),
    last_used_at  timestamptz,
    revoked_at    timestamptz
);
CREATE INDEX api_keys_business_idx ON api_keys (business_id);

CREATE TABLE customers (
    id           uuid PRIMARY KEY,
    business_id  uuid NOT NULL REFERENCES businesses (id),
    name         text NOT NULL,
    email        text NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    -- Lets invoices reference (customer, business) together, so a business
    -- can never bill another business's customer.
    UNIQUE (id, business_id)
);
CREATE INDEX customers_business_idx ON customers (business_id, id DESC);

CREATE TABLE invoices (
    id           uuid PRIMARY KEY,
    business_id  uuid NOT NULL REFERENCES businesses (id),
    customer_id  uuid NOT NULL,
    state        text NOT NULL
                 CHECK (state IN ('open', 'locked', 'uncollectible', 'paid', 'void')),
    -- Where a locked invoice returns to if the payment fails.
    prev_state   text CHECK (prev_state IN ('open', 'uncollectible')),
    locked_at    timestamptz,
    total_cents  bigint NOT NULL CHECK (total_cents >= 0),
    currency     text NOT NULL DEFAULT 'USD' CHECK (currency = 'USD'),
    due_date     date NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    updated_at   timestamptz NOT NULL DEFAULT now(),
    FOREIGN KEY (customer_id, business_id) REFERENCES customers (id, business_id),
    -- prev_state and locked_at are set exactly when the invoice is locked.
    CONSTRAINT locked_fields_consistent
        CHECK ((state = 'locked') = (prev_state IS NOT NULL AND locked_at IS NOT NULL))
);
CREATE INDEX invoices_business_state_idx ON invoices (business_id, state, id DESC);
CREATE INDEX invoices_business_idx ON invoices (business_id, id DESC);
-- Small index the reconciler scans for stuck payments.
CREATE INDEX invoices_locked_idx ON invoices (locked_at) WHERE state = 'locked';

CREATE TABLE invoice_line_items (
    id                 uuid PRIMARY KEY,
    invoice_id         uuid NOT NULL REFERENCES invoices (id),
    position           integer NOT NULL,
    description        text NOT NULL,
    quantity           integer NOT NULL CHECK (quantity > 0),
    unit_amount_cents  bigint NOT NULL CHECK (unit_amount_cents >= 0),
    amount_cents       bigint NOT NULL,
    CHECK (amount_cents = quantity * unit_amount_cents),
    UNIQUE (invoice_id, position)
);

-- One row per try at paying an invoice. The id is also the PSP idempotency key.
CREATE TABLE payment_attempts (
    id            uuid PRIMARY KEY,
    invoice_id    uuid NOT NULL REFERENCES invoices (id),
    business_id   uuid NOT NULL REFERENCES businesses (id),
    amount_cents  bigint NOT NULL CHECK (amount_cents >= 0),
    card_token    text NOT NULL,
    status        text NOT NULL
                  CHECK (status IN ('pending', 'succeeded', 'failed', 'abandoned')),
    failure_code  text,
    psp_ref       text,
    created_at    timestamptz NOT NULL DEFAULT now(),
    updated_at    timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX payment_attempts_invoice_idx ON payment_attempts (invoice_id);
-- Last line of defense: even with a code bug, an invoice can never have two
-- in-flight attempts or two successful ones.
CREATE UNIQUE INDEX one_pending_attempt_per_invoice
    ON payment_attempts (invoice_id) WHERE status = 'pending';
CREATE UNIQUE INDEX one_succeeded_attempt_per_invoice
    ON payment_attempts (invoice_id) WHERE status = 'succeeded';

-- Idempotency-Key records for POST /invoices/{id}/pay, scoped per business.
-- A row with neither attempt_id nor response is "in progress".
CREATE TABLE idempotency_keys (
    business_id      uuid NOT NULL REFERENCES businesses (id),
    key              text NOT NULL CHECK (char_length(key) BETWEEN 1 AND 255),
    request_hash     bytea NOT NULL,
    attempt_id       uuid REFERENCES payment_attempts (id),
    response_status  smallint,
    response_body    jsonb,
    created_at       timestamptz NOT NULL DEFAULT now(),
    claimed_at       timestamptz NOT NULL DEFAULT now(),
    PRIMARY KEY (business_id, key)
);

CREATE TABLE webhook_endpoints (
    id           uuid PRIMARY KEY,
    business_id  uuid NOT NULL REFERENCES businesses (id),
    url          text NOT NULL,
    -- Needed in plaintext to compute HMAC signatures. In production this
    -- would be encrypted with a KMS key.
    secret       text NOT NULL,
    enabled      boolean NOT NULL DEFAULT true,
    created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX webhook_endpoints_business_idx ON webhook_endpoints (business_id);

-- Outbox: written in the same transaction as the state change that caused it.
CREATE TABLE events (
    id           uuid PRIMARY KEY,
    business_id  uuid NOT NULL REFERENCES businesses (id),
    type         text NOT NULL,
    invoice_id   uuid NOT NULL REFERENCES invoices (id),
    payload      jsonb NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX events_business_idx ON events (business_id, id);

CREATE TABLE webhook_deliveries (
    id                    uuid PRIMARY KEY,
    event_id              uuid NOT NULL REFERENCES events (id),
    endpoint_id           uuid NOT NULL REFERENCES webhook_endpoints (id),
    status                text NOT NULL CHECK (status IN ('pending', 'succeeded', 'dead')),
    attempt_count         integer NOT NULL DEFAULT 0,
    next_attempt_at       timestamptz NOT NULL DEFAULT now(),
    last_attempt_at       timestamptz,
    last_response_status  integer,
    last_error            text,
    created_at            timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX webhook_deliveries_due_idx
    ON webhook_deliveries (next_attempt_at) WHERE status = 'pending';
CREATE INDEX webhook_deliveries_event_idx ON webhook_deliveries (event_id);
